  const complete='select public.caro_complete_trial_event($1,$2,$3,$4) result';await assert.rejects(()=>db.query(complete,[events[0],ordered.reviewToken,crypto.randomUUID(),'Fictional signed record']),/every active run/);
  const score='select public.caro_record_judge_score($1,$2,$3,$4,$5,$6,$7,$8,$9) result';const first=ordered.runs[0],second=ordered.runs[1],scoreKey=crypto.randomUUID();
