  const sql='select public.caro_save_practice_trial_draft($1,$2,$3,$4,$5,$6,$7,$8) result',args=[trial,club,-1,'Practice weekend','2027-04-17','2027-04-18','America/Edmonton',planning];
  const created=(await one(sql,args)).result;assert.equal(created.is_practice,true);assert.equal(created.revision,1);assert.deepEqual((await one(sql,args)).result,created);
