  await db.query("insert into public.caro_entry_settings(trial_id,club_id,opens_on,closes_on,pricing,agreement_version,premium_draft_revision,revision,updated_by) select $1,s.club_id,s.opens_on,s.closes_on,(select jsonb_agg(price||jsonb_build_object('event_id',e.id)) from jsonb_array_elements(s.pricing) price join public.caro_events old on old.id=(price->>'event_id')::uuid join public.caro_events e on e.trial_id=$1 and e.local_key=old.local_key),s.agreement_version,0,0,s.updated_by from public.caro_entry_settings s where s.trial_id=$2",[trial,source]);
  await as(owner);const config=(await one('select public.caro_manual_entry_configuration($1) result',[trial])).result;assert.equal(config.fictional,true);
  await assert.rejects(()=>db.query('select public.caro_publication_preview($1)',[trial]),/cannot be published/);
